-- CadencePlus Solutions Kora free starter v1.0
-- Local SQL Server route. Run 00_Create_Database.sql first, then this entire file.
-- Contains data directly. CSV import and server file access are not required.
USE [KoraStarter];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
IF DB_NAME() <> N'KoraStarter' THROW 51000, 'Use the KoraStarter database only.', 1;
IF SCHEMA_ID(N'kora') IS NOT NULL THROW 51001, 'The kora schema already exists. Stop and use a new empty database or your existing loaded copy.', 1;
BEGIN TRY
BEGIN TRANSACTION;
EXEC(N'CREATE SCHEMA [kora]');

CREATE TABLE [kora].[regions] (
  [region_id] NVARCHAR(200) NOT NULL PRIMARY KEY,
  [region_name] NVARCHAR(200) NOT NULL,
  [country] NVARCHAR(200) NOT NULL
);


CREATE TABLE [kora].[branches] (
  [branch_id] NVARCHAR(200) NOT NULL PRIMARY KEY,
  [branch_name] NVARCHAR(200) NOT NULL,
  [region_id] NVARCHAR(200) NOT NULL,
  [city] NVARCHAR(200) NOT NULL,
  FOREIGN KEY ([region_id]) REFERENCES [kora].[regions]([region_id])
);


CREATE TABLE [kora].[customers] (
  [customer_id] NVARCHAR(200) NOT NULL PRIMARY KEY,
  [customer_name] NVARCHAR(200) NOT NULL,
  [region_id] NVARCHAR(200) NOT NULL,
  [industry] NVARCHAR(200) NOT NULL,
  [segment] NVARCHAR(200) NOT NULL,
  FOREIGN KEY ([region_id]) REFERENCES [kora].[regions]([region_id])
);




CREATE TABLE [kora].[products] (
  [product_id] NVARCHAR(200) NOT NULL PRIMARY KEY,
  [product_name] NVARCHAR(200) NOT NULL,
  [category] NVARCHAR(200) NOT NULL,
  [unit_of_measure] NVARCHAR(200) NOT NULL,
  [launch_date] DATE NOT NULL,
  [is_active] INT NOT NULL
);


CREATE TABLE [kora].[orders] (
  [order_id] NVARCHAR(200) NOT NULL PRIMARY KEY,
  [order_date] DATE NOT NULL,
  [customer_id] NVARCHAR(200) NOT NULL,
  [branch_id] NVARCHAR(200) NOT NULL,
  [channel] NVARCHAR(200) NOT NULL,
  [promised_delivery_date] DATE NOT NULL,
  [status] NVARCHAR(200) NOT NULL,
  [cancellation_reason] NVARCHAR(200) NULL,
  FOREIGN KEY ([customer_id]) REFERENCES [kora].[customers]([customer_id]),
  FOREIGN KEY ([branch_id]) REFERENCES [kora].[branches]([branch_id]),
  CHECK (status IN ('Delivered','Partially delivered','Pending','Cancelled'))
);

















CREATE TABLE [kora].[order_lines] (
  [order_line_id] NVARCHAR(200) NOT NULL PRIMARY KEY,
  [order_id] NVARCHAR(200) NOT NULL,
  [product_id] NVARCHAR(200) NOT NULL,
  [ordered_quantity] INT NOT NULL,
  [list_unit_price_ngn] DECIMAL(18,2) NOT NULL,
  [discount_percent] INT NOT NULL,
  [gross_order_value_ngn] DECIMAL(18,2) NOT NULL,
  [discount_value_ngn] DECIMAL(18,2) NOT NULL,
  [net_order_value_ngn] DECIMAL(18,2) NOT NULL,
  FOREIGN KEY ([order_id]) REFERENCES [kora].[orders]([order_id]),
  FOREIGN KEY ([product_id]) REFERENCES [kora].[products]([product_id]),
  CHECK (ordered_quantity > 0),
  CHECK (discount_percent BETWEEN 0 AND 100),
  CHECK (net_order_value_ngn >= 0)
);








































CREATE TABLE [kora].[deliveries] (
  [delivery_id] NVARCHAR(200) NOT NULL PRIMARY KEY,
  [order_id] NVARCHAR(200) NOT NULL,
  [branch_id] NVARCHAR(200) NOT NULL,
  [carrier] NVARCHAR(200) NOT NULL,
  [promised_delivery_date] DATE NOT NULL,
  [dispatch_date] DATE NULL,
  [delivered_date] DATE NULL,
  [status] NVARCHAR(200) NOT NULL,
  [shipping_cost_ngn] DECIMAL(18,2) NOT NULL,
  [exception_reason] NVARCHAR(200) NULL,
  FOREIGN KEY ([order_id]) REFERENCES [kora].[orders]([order_id]),
  FOREIGN KEY ([branch_id]) REFERENCES [kora].[branches]([branch_id]),
  CHECK (status IN ('Delivered','Failed','In transit','Scheduled')),
  CHECK ((status = 'Delivered' AND delivered_date IS NOT NULL) OR (status <> 'Delivered' AND delivered_date IS NULL))
);


















CREATE INDEX [ix_branches_region_id] ON [kora].[branches]([region_id]);
CREATE INDEX [ix_customers_region_id] ON [kora].[customers]([region_id]);
CREATE INDEX [ix_orders_customer_id] ON [kora].[orders]([customer_id]);
CREATE INDEX [ix_orders_branch_id] ON [kora].[orders]([branch_id]);
CREATE INDEX [ix_orders_order_date] ON [kora].[orders]([order_date]);
CREATE INDEX [ix_order_lines_order_id] ON [kora].[order_lines]([order_id]);
CREATE INDEX [ix_order_lines_product_id] ON [kora].[order_lines]([product_id]);
CREATE INDEX [ix_deliveries_order_id] ON [kora].[deliveries]([order_id]);
CREATE INDEX [ix_deliveries_branch_id] ON [kora].[deliveries]([branch_id]);
IF (SELECT COUNT(*) FROM [kora].[regions]) <> 6 THROW 51002, 'Row count mismatch for regions.', 1;
IF (SELECT COUNT(*) FROM [kora].[branches]) <> 6 THROW 51002, 'Row count mismatch for branches.', 1;
IF (SELECT COUNT(*) FROM [kora].[customers]) <> 1100 THROW 51002, 'Row count mismatch for customers.', 1;
IF (SELECT COUNT(*) FROM [kora].[products]) <> 54 THROW 51002, 'Row count mismatch for products.', 1;
IF (SELECT COUNT(*) FROM [kora].[orders]) <> 6001 THROW 51002, 'Row count mismatch for orders.', 1;
IF (SELECT COUNT(*) FROM [kora].[order_lines]) <> 15491 THROW 51002, 'Row count mismatch for order_lines.', 1;
IF (SELECT COUNT(*) FROM [kora].[deliveries]) <> 6408 THROW 51002, 'Row count mismatch for deliveries.', 1;
COMMIT TRANSACTION;
END TRY
BEGIN CATCH
IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
THROW;
END CATCH;
SELECT N'Kora starter loaded successfully' AS result;
